class VectorClock:
    def __init__(self, n, me):
        self.v = [0] * n
        self.me = me  # 자기 노드 인덱스

    def tick(self):  # 로컬 이벤트·송신
        self.v[self.me] += 1
        return list(self.v)

    def receive(self, other):  # 원소별 max 후 증가
        self.v = [max(a, b) for a, b in zip(self.v, other)]
        self.v[self.me] += 1

def compare(a, b):
    if a == b:
        return 'equal'
    if all(x <= y for x, y in zip(a, b)):
        return 'a → b'  # a가 b에 인과적으로 선행
    if all(x >= y for x, y in zip(a, b)):
        return 'b → a'
    return 'concurrent'  # 동시 갱신(충돌)
